local TaperRollerMaker = {}
local PRODUCTS = {
    iron_taper_roller = { name = "Železni valjalec za tanke sveče", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 175, prestige = 4, happiness = 2, description = "Železni valjalec za izdelavo tankih sveč." },
    bronze_taper_roller = { name = "Bronast valjalec za tanke sveče", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 425, prestige = 6, happiness = 3, description = "Bronast valjalec za enakomerne tanke sveče." },
    silver_taper_roller = { name = "Srebrni valjalec za tanke sveče", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 1025, prestige = 11, happiness = 4, description = "Srebrni valjalec za plemiške tanke sveče." },
    gilded_taper_roller = { name = "Pozlačeni valjalec za tanke sveče", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 2200, prestige = 20, happiness = 5, description = "Pozlačeni valjalec za dvorne tanke sveče." },
    jewel_set_taper_roller = { name = "Draguljasti valjalec za tanke sveče", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4750, prestige = 36, happiness = 7, description = "Draguljasti valjalec za kraljevske tanke sveče." },
    royal_sovereign_taper_roller = { name = "Kraljevski suvereni valjalec za tanke sveče", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 10200, prestige = 70, happiness = 13, description = "Suvereni valjalec z biseri za krono." },
}
local BUILDINGS = {
    taperroller_workshop = { name = "Valjalna delavnica", cost = { gold = 345, wood = 180, stone = 140, iron = 9 }, upkeep = 7, qualityBonus = 5 },
    taperroller_house = { name = "Valjalna hiša", cost = { gold = 1240, wood = 365, stone = 280, silver = 7, iron = 8 }, upkeep = 26, qualityBonus = 18 },
    master_taperroller_atelier = { name = "Mojstrski valjalni atelje", cost = { gold = 3100, wood = 425, stone = 530, silver = 36, gold = 7 }, upkeep = 73, qualityBonus = 30 },
    sovereign_taperroller_palace = { name = "Suverena valjalna palača", cost = { gold = 13200, wood = 655, stone = 840, gold = 85, jewel = 19 }, upkeep = 258, qualityBonus = 55, prestigeBonus = 50 },
}
TaperRollerMaker.ironStock = 14; TaperRollerMaker.bronzeStock = 12; TaperRollerMaker.woodStock = 14; TaperRollerMaker.leatherStock = 10; TaperRollerMaker.silverStock = 8; TaperRollerMaker.goldStock = 6; TaperRollerMaker.jewelStock = 4; TaperRollerMaker.pearlStock = 4
TaperRollerMaker.productStock = {}; TaperRollerMaker.buildings = {}; TaperRollerMaker.maker = nil; TaperRollerMaker.activeMaking = {}; TaperRollerMaker.totalProducts = 0; TaperRollerMaker.dayTimer = 0
function TaperRollerMaker.init() TaperRollerMaker.ironStock=14; TaperRollerMaker.bronzeStock=12; TaperRollerMaker.woodStock=14; TaperRollerMaker.leatherStock=10; TaperRollerMaker.silverStock=8; TaperRollerMaker.goldStock=6; TaperRollerMaker.jewelStock=4; TaperRollerMaker.pearlStock=4; TaperRollerMaker.productStock={}; TaperRollerMaker.buildings={}; TaperRollerMaker.maker=nil; TaperRollerMaker.activeMaking={}; TaperRollerMaker.totalProducts=0; TaperRollerMaker.dayTimer=0; print("[TaperRollerMaker] Royal Taper Roller Maker System initialized (6 products, 4 buildings)") end
function TaperRollerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TaperRollerMaker.maker={name=n or ("Valjalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjalec najet: %s (spretnost: %d)",TaperRollerMaker.maker.name,s),"success") end; return true end
function TaperRollerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TaperRollerMaker.build(id) local ok,e=TaperRollerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TaperRollerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TaperRollerMaker.getQualityBonus() local b=0; for _,bd in ipairs(TaperRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TaperRollerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and TaperRollerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and TaperRollerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and TaperRollerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TaperRollerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and TaperRollerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TaperRollerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TaperRollerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TaperRollerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TaperRollerMaker.buildings==0 then return false,"Potrebna valjalna delavnica" end; if not TaperRollerMaker.maker then return false,"Potreben valjalec" end; return true end
function TaperRollerMaker.make(pt,qty) qty=qty or 1; local ok,e=TaperRollerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then TaperRollerMaker.ironStock=TaperRollerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then TaperRollerMaker.bronzeStock=TaperRollerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then TaperRollerMaker.woodStock=TaperRollerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TaperRollerMaker.leatherStock=TaperRollerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then TaperRollerMaker.silverStock=TaperRollerMaker.silverStock-d.silverCost*qty end; if d.goldCost then TaperRollerMaker.goldStock=TaperRollerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TaperRollerMaker.jewelStock=TaperRollerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TaperRollerMaker.pearlStock=TaperRollerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TaperRollerMaker.maker then t=math.max(1,t-math.floor(TaperRollerMaker.maker.skill/13)) end; table.insert(TaperRollerMaker.activeMaking,{id="taperroller_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TaperRollerMaker.completeMaking(m) local q=1.0+(TaperRollerMaker.getQualityBonus()/100); if TaperRollerMaker.maker then q=q+(TaperRollerMaker.maker.skill/140) end; q=math.min(2.5,q); TaperRollerMaker.productStock[m.productType]=(TaperRollerMaker.productStock[m.productType] or 0)+m.quantity; TaperRollerMaker.totalProducts=TaperRollerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TaperRollerMaker.maker then TaperRollerMaker.maker.itemsMade=TaperRollerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TaperRollerMaker.maker.skill=math.min(100,TaperRollerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"taperroller.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function TaperRollerMaker.update(dt) if not _G.state then return end; TaperRollerMaker.dayTimer=TaperRollerMaker.dayTimer+dt; if TaperRollerMaker.dayTimer>=30 then TaperRollerMaker.dayTimer=0; for i=#TaperRollerMaker.activeMaking,1,-1 do local m=TaperRollerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TaperRollerMaker.completeMaking(m); table.remove(TaperRollerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TaperRollerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TaperRollerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TaperRollerMaker.getStats() return {ironStock=TaperRollerMaker.ironStock,bronzeStock=TaperRollerMaker.bronzeStock,woodStock=TaperRollerMaker.woodStock,leatherStock=TaperRollerMaker.leatherStock,silverStock=TaperRollerMaker.silverStock,goldStock=TaperRollerMaker.goldStock,jewelStock=TaperRollerMaker.jewelStock,pearlStock=TaperRollerMaker.pearlStock,productStock=TaperRollerMaker.productStock,numBuildings=#TaperRollerMaker.buildings,hasMaker=TaperRollerMaker.maker~=nil,makerName=TaperRollerMaker.maker and TaperRollerMaker.maker.name or "—",makerSkill=TaperRollerMaker.maker and TaperRollerMaker.maker.skill or 0,activeMaking=#TaperRollerMaker.activeMaking,totalProducts=TaperRollerMaker.totalProducts} end
return TaperRollerMaker
